package com.andye.warmod.antiair.client.audio;
import net.minecraft.client.resources.sounds.*;import net.minecraft.sounds.*;import net.minecraft.util.RandomSource;import net.minecraft.world.phys.Vec3;
public final class AntiAirEngineLoopSound extends AbstractTickableSoundInstance{private float targetVolume;private int fade=-1,total=1;public AntiAirEngineLoopSound(SoundEvent event,Vec3 position,float pitch){super(event,SoundSource.BLOCKS,RandomSource.create());looping=true;delay=0;attenuation=SoundInstance.Attenuation.NONE;relative=false;this.pitch=pitch;update(position,.001F);}public void update(Vec3 p,float volume){x=p.x;y=p.y;z=p.z;targetVolume=Math.max(0,volume);}public void fadeOut(int ticks){if(fade<0){fade=total=Math.max(1,ticks);}}@Override public boolean canStartSilent(){return true;}@Override public void tick(){float f=1;if(fade>=0){f=fade--/(float)total;if(fade<0){volume=0;stop();return;}}volume=Math.max(.001F,targetVolume*f);}}
